    BIO *cert_bio = NULL;
    unsigned char *der_cert = NULL;
    int der_len = 0;
    unsigned char hash[EVP_MAX_MD_SIZE]; // Buffer for the raw hash bytes
    unsigned int hash_len;
    char *hex_hash_result = NULL; // This will hold the final result to be returned
    EVP_MD_CTX *md_ctx = NULL;
    char *temp_hex_buffer = NULL; // Temporary buffer for hex string

