    if (!cert) {
        goto cleanup;
    }

    // 2. Create a BIO from the input certificate string (assuming PEM format)
    cert_bio = BIO_new_mem_buf(cert, -1); // -1 means BIO_new_mem_buf will use strlen(cert)
    if (!cert_bio) {
        goto cleanup;
    }

    // 3. Read the X509 certificate from the BIO
    x509_cert = PEM_read_bio_X509(cert_bio, NULL, NULL, NULL);
